"""GT-1 parameter spec (generated by tools/build_gt1_spec.py) and patch value conversions."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import cache
from pathlib import Path

from .sysex import addr_add, parse_addr

SPEC_PATH = Path(__file__).parent / "data" / "gt1_spec.json"


@dataclass(frozen=True)
class Block:
    addr34: list[int]  # address bytes 3-4 inside a patch area
    size: int


class GT1Spec:
    def __init__(self, raw: dict):
        self.raw = raw
        self.model_id: list[int] = raw["model_id"]
        self.blocks = [Block(parse_addr(a), n) for a, n in raw["blocks"]]
        self.defs: dict[str, dict] = raw["defs"]
        self.commands = {k: parse_addr(v) for k, v in raw["commands"].items()}
        self.system = {k: parse_addr(v) for k, v in raw["system"].items()}
        # field -> offset (address bytes 3-4 as a 14-bit 7-bit-packed int) inside a patch area
        self.field_off: dict[str, int] = {}
        for f, a in raw["fields"].items():
            hi, lo = parse_addr(a)
            self.field_off[f] = (hi << 7) | lo
        self.off_field = {v: k for k, v in self.field_off.items()}
        # combined 14-bit values stored as <name>_h / <name>_l byte pairs
        self.combined = sorted({f[:-2] for f in self.field_off if f.endswith("_h")
                                and f[:-2] + "_l" in self.field_off})

    # -- areas ----------------------------------------------------------------------------------
    def temp_area(self) -> list[int]:
        return list(self.raw["temp_top"])

    @staticmethod
    def user_area(slot: int) -> list[int]:
        """slot is 0-based (U01 = 0 ... U99 = 98)."""
        if not 0 <= slot <= 98:
            raise ValueError("GT-1 user slots are U01..U99")
        return [0x10, slot]

    def block_addrs(self, area: list[int]):
        for b in self.blocks:
            yield b, [*area, *b.addr34]

    def block_fields(self, b: Block) -> list[str | None]:
        start = (b.addr34[0] << 7) | b.addr34[1]
        return [self.off_field.get(start + i) for i in range(b.size)]

    # -- value conversion -----------------------------------------------------------------------
    def display_to_raw(self, field: str, value) -> int:
        """Convert a display value (number shown in BTS, or option name) to the raw device byte(s)."""
        d = self.defs.get(field)
        if d is None:
            raise KeyError(f"no definition for {field}")
        if isinstance(value, str):
            opts = d.get("options") or []
            norm = [o.upper().replace(" ", "") for o in opts]
            key = value.upper().replace(" ", "")
            if key in norm:
                return norm.index(key)
            dd = {v.upper().replace(" ", ""): int(k) for k, v in d.get("dropdown", {}).items()}
            if key in dd:
                return dd[key]
            raise ValueError(f"{field}: unknown option {value!r}; valid: {opts}")
        lo, hi, step = d.get("min", 0), d.get("max", 127), d.get("step", 1)
        if "options" in d and lo == 0:
            return int(max(0, min(len(d["options"]) - 1, round(value))))
        v = max(lo, min(hi, value))
        offset = lo if lo < 0 else 0
        return int(round((v - offset) / step))

    def raw_to_display(self, field: str, raw: int):
        d = self.defs.get(field, {})
        if d.get("options") and d.get("min", 0) == 0 and 0 <= raw < len(d["options"]):
            return d["options"][raw]
        if "dropdown" in d and str(raw) in d["dropdown"]:
            return d["dropdown"][str(raw)]
        lo, step = d.get("min", 0), d.get("step", 1)
        return raw * step + (lo if lo < 0 else 0)

    def options(self, field: str) -> list[str]:
        return list(self.defs.get(field, {}).get("options", []))


@cache
def load_spec() -> GT1Spec:
    return GT1Spec(json.loads(SPEC_PATH.read_text(encoding="utf-8")))


__all__ = ["GT1Spec", "Block", "load_spec", "addr_add"]
